public static <V, E> void generateBipartiteGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // We will generate the graph by iterating over the vertices in the first
    // partition and connecting them to all vertices in the second partition.
    List<V> firstPartition = new ArrayList<>(target.getVertexCount() / 2);
    List<V> secondPartition = new ArrayList<>(target.getVertexCount() / 2);
    for (V vertex : target.getVertices()) {
        // If the vertex has not been assigned to a partition, add it to the first partition
        if (!resultMap.containsKey(vertex.toString())) {
            firstPartition.add(vertex);
            resultMap.put(vertex.toString(), vertex);
        } else {
            secondPartition.add(resultMap.get(vertex.toString()));
        }
    }

    // Add edges between vertices in the first and second partition
    for (V first : firstPartition) {
        for (V second : secondPartition) {
            target.addEdge(first, second, "");
        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Generate a set of vertices from the map
        Set<V> vertices = new HashSet<>(resultMap.values());
        // Iterate over each vertex in the set
        for (V vertex : vertices) {
            // Add the vertex to the graph
            target.addVertex(vertex);
            // Get the neighbors of the vertex
            Set<V> neighbors = GraphUtils.getNeighbors(resultMap, vertex);
            // Iterate over each neighbor
            for (V neighbor : neighbors) {
                // Add an edge between the vertex and its neighbors
                target.addEdge(vertex, neighbor);
            }
        }
    }

public void generateGraph(Map<String, V> resultMap) {
    Graph<V,E> target = new Graph<>();
    Set<V> lhsVertices = resultMap.keySet();
    Set<V> rhsVertices = new HashSet<>();
    for (V v : lhsVertices) {
        rhsVertices.add(resultMap.get(v));
    }
    target.addVertices(lhsVertices, rhsVertices);
    for (V v : lhsVertices) {
        E e = target.addEdge(v, resultMap.get(v));
        target.setEdgeWeight(e, 1.0);
    }
    for (V v : rhsVertices) {
        for (V w : rhsVertices) {
            if (v != w) {
                E e = target.addEdge(v, w);
                target.setEdgeWeight(e, 1.0);
            }
        }
    }
}

public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Generate a random number of vertices and edges
    int vertexCount = RandomUtils.nextInt(10, 21);
    int edgeCount = RandomUtils.nextInt(0, Math.min(vertexCount * (vertexCount - 1) / 2, 50));

    // Initialize the graph and the result map
    target.clear();
    resultMap.clear();
    for (int i = 0; i < vertexCount; i++) {
        V v = new V();
        target.addVertex(v);
        resultMap.put("v" + i, v);
    }

    // Generate edges
    for (int i = 0; i < edgeCount; i++) {
        int v1Index = RandomUtils.nextInt(0, vertexCount);
        int v2Index = RandomUtils.nextInt(0, vertexCount - 1);
        if (v1Index != v2Index) {
            E e = new E(resultMap.get("v" + v1Index), resultMap.get("v" + v2Index));
            target.addEdge(e);
        }
    }
}

