public int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    int startPos = out.position();
    ByteWriter writer = new ByteWriter(buffer);
    byte[] messageBytes = writer.writeDelimitedTo(message, schema, buffer);
    out.write(messageBytes, 0, messageBytes.length);
    int endPos = out.position();
    return endPos - startPos;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    int size = schema.size(message);
    out.writeInt32(size);
    schema.write(out, message, buffer);
    buffer.writeTo(out);
    return size;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    int size = writeRaw(buffer, message, schema);
    writeRawVarint32(buffer, size);
    out.write(buffer.data, 0, size + buffer.sizeFieldSize);
    return size;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message using the specified schema, and wrap the result with its length prefixed
    byte[] messageBytes = schema.serialize(message);
    int messageLength = messageBytes.length;
    VarInt.putVarInt(messageLength, buffer);
    out.write(buffer.data, 0, VarInt.varIntSize(messageLength));
    out.write(messageBytes, 0, messageLength);
    return messageLength;
}

