public Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        if (targetType.isAssignableFrom(parameterizedType.getRawType())) {
            TypeVariable<?>[] typeParameters = parameterizedType.getRawType().getTypeParameters();
            if (typeArguments.length == typeParameters.length) {
                Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
                for (int i = 0; i < typeArguments.length; i++) {
                    resolvedArguments[i] = findConcreteType(typeArguments[i], typeParameters[i], targetType);
                }
                return resolvedArguments;
            }
        }
    }
    return null;
}

private static Class<?> findConcreteType(Type type, TypeVariable<?> variable, Class<?> targetType) {
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        if (parameterizedType.getRawType().equals(targetType)) {
            Type[] typeArguments = parameterizedType.getActualTypeArguments();
            for (int i = 0; i < typeArguments.length; i++) {
                if (typeArguments[i].equals(variable)) {
                    return (Class<?>) typeArguments[i];
                }
            }
        }
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    Class<?>[] parameterClasses = null;
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        if (actualTypeArguments.length > 0) {
            parameterClasses = new Class<?>[actualTypeArguments.length];
            for (int i = 0; i < actualTypeArguments.length; i++) {
                Type actualTypeArgument = actualTypeArguments[i];
                parameterClasses[i] = typeToClass(actualTypeArgument, targetType);
            }
        }
    }
    return parameterClasses;
}

private static Class<?> typeToClass(Type type, Class<?> targetType) {
    Class<?> parameterClass;
    if (type instanceof Class) {
        parameterClass = (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type rawType = parameterizedType.getRawType();
        if (rawType instanceof Class) {
            parameterClass = (Class<?>) rawType;
        } else {
            parameterClass = targetType;
        }
    } else {
        parameterClass = targetType;
    }
    return parameterClass;
}

public static Class[] resolveArguments(Type genericType, Class targetType) {
    if (!genericType.IsGenericType) return null; // Check if generic type is parameterized

    // Get type variable information from target type
    Type[] typeArguments = genericType.GetGenericArguments();

    // Resolve and return type arguments for generic type
    return typeArguments.Select(ResolveTypeArgument).ToArray();
}

private static Class ResolveTypeArgument(Type typeArgument) {
    // Check if type argument is type variable, if not return type argument itself
    if (!typeArgument.IsGenericParameter) return typeArgument;

    // Get runtime type of type argument
    RuntimeTypeHandle typeArgumentHandle = typeArgument.UnderlyingSystemType.GetTypeHandle();
    RuntimeType typeArgumentRuntimeType = typeArgumentHandle.GetRuntimeType();

    // If type argument is object or value type, return corresponding system type
    if (typeArgumentRuntimeType.IsObjectType() || typeArgumentRuntimeType.IsValueType())
        return typeArgumentRuntimeType.SystemType;

    // Check if type argument has matching type variable for target type
    Type[] targetTypeTypeParameters = targetType.GetGenericTypeArguments();
    Type[] typeParameterBindings = typeArgumentRuntimeType.GetTypeParameterBindings();
    for (int i = 0; i < targetTypeTypeParameters.Length; i++) {
        if (targetTypeTypeParameters[i].GetGenericParameterPosition() == typeArgumentRuntimeType.GetGenericParameterPosition())
            return targetTypeTypeParameters[i];
    }

    // If type argument does not have matching type variable, return type argument itself
    return typeArgumentRuntimeType.SystemType;
}

public static Class<?>[] resolveArguments(Type genericType,Class<?> targetType){
    if(genericType instanceof ParameterizedType){
        ParameterizedType parameterizedType = (ParameterizedType)genericType;
        Type[] arguments = parameterizedType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[arguments.length];
        for(int i = 0; i < arguments.length; i++){
            result[i] = getTypeArgument(arguments[i], targetType);
        }
        return result;
    }
    return null;
}

private static Class<?> getTypeArgument(Type argument,Class<?> targetType){
    if(argument instanceof Class){
        return (Class<?>)argument;
    }else if(argument instanceof TypeVariable){
        return getTypeVariableArgument((TypeVariable)argument, targetType);
    }else if(argument instanceof ParameterizedType){
        return getParameterizedTypeArgument((ParameterizedType)argument, targetType);
    }
    return null;
}

private static Class<?> getTypeVariableArgument(TypeVariable variable,Class<?> targetType){
    final Class<?>[] typeParameters = targetType.getTypeParameters();
    for(int i = 0; i < typeParameters.length; i++){
        if(variable.getName().equals(typeParameters[i].getName())){
            return typeParameters[i];
        }
    }
    return null;
}

private static Class<?> getParameterizedTypeArgument(ParameterizedType parameterizedType, Class<?> targetType){
    Type rawType = parameterizedType.getRawType();
    if(rawType instanceof Class){
        return (Class<?>)rawType;
    }else if(rawType instanceof TypeVariable){
        return getTypeVariableArgument((TypeVariable)rawType, targetType);
    }
    return null;
}

