    // Method to return mappings with fields that not exist in the input mappings
    // Input: mappings - current index history structure
    // Input: tableName - current index name
    // Return: mappings not found in current index

    // Get the backup mapping
    Mappings backupMapping = mappings.getBackUpMapping();

    // Loop through the current index mapping fields
    for (Field field : mappings.getFields()) {
        // Check whether the field exists in the backup mapping
        if (!backupMapping.containsKey(field)) {
            // Add the field to the diff mappings
            Mappings diffMappings = new Mappings();
            diffMappings.put(field, mappings.get(field));

            // Update the diff mappings with the table name
            diffMappings.setTableName(tableName);

            // Return the diff mappings
            return diffMappings;
        }
    }

    // If all fields are found in the backup mapping, return an empty mappings
    return new Mappings();
}

