public int findFirstUnusedChannelIndex() {
    // Create a list of all the channel indices in use
    List<Integer> inUseIndices = new ArrayList<Integer>();
    for (Channel c : targetChannels) {
        inUseIndices.add(c.getIndex());
    }

    // Find the first gap in the list of indices
    int firstUnusedIndex = -1;
    for (int i = 0; i < inUseIndices.size(); i++) {
        int index = inUseIndices.get(i);
        if (i > 0 && index == inUseIndices.get(i - 1) + 1) {
            continue;
        }
        if (firstUnusedIndex == -1) {
            firstUnusedIndex = index + 1;
        } else if (index > firstUnusedIndex) {
            firstUnusedIndex = index;
        }
    }
    return firstUnusedIndex;
}

