public long readLong(final int offset) {
    // Check if the current position is within the bounds of the input stream
    if (offset < 0 || offset >= this.data.length) {
        throw new IndexOutOfBoundsException("Offset out of bounds: " + offset);
    }

    // Read the long value from the input stream
    long value = this.data[offset];

    // Check if the value is signed, if so flip the bits to get the correct value
    if (value < 0) {
        value = ~value;
    }

    return value;
}

