void buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end && (end - start) < FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, Math.min(start + FETCH_DATA_DURATION, end)));
        start += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

public static List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> ranges = new ArrayList<>();
        while (start < end) {
            long rangeStart = start;
            long rangeEnd = Math.min(end, start + FETCH_DATA_DURATION);
            ranges.add(new TimeRange(rangeStart, rangeEnd));
            start = rangeEnd;
        }
        return ranges;
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long rangeStart = start;
        long rangeEnd = end < start + FETCH_DATA_DURATION ? end : start + FETCH_DATA_DURATION;
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
        start += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long startTime = start;
    long endTime = end;
    while (startTime <= endTime) {
        TimeRange range = new TimeRange(startTime, Math.min(endTime, startTime + FETCH_DATA_DURATION - 1));
        timeRanges.add(range);
        startTime = Math.min(startTime + FETCH_DATA_DURATION, endTime - 1);
    }
    return timeRanges;
}

