static long compressTimeBucket(long timeBucket, int dayStep) {
    // Convert the timeBucket to a string
    String timeString = Long.toString(timeBucket);

    // Extract the day of the month from the timeString
    String dayOfMonth = timeString.substring(6, 10);

    // Convert the dayStep to a string
    String stepString = Integer.toString(dayStep);

    // Subtract 1 from the dayStep if it's not 1
    if (Integer.parseInt(stepString) != 1) {
        stepString = Integer.toString(Integer.parseInt(stepString) - 1);
    }

    // Split the day of the month into an array of characters
    char[] dayOfMonthArray = dayOfMonth.toCharArray();

    // Modify the last digit of the day of the month based on the stepString
    dayOfMonthArray[dayOfMonthArray.length - 1] += Integer.parseInt(stepString);

    // Join the modified day of the month and the year
    String newDayOfMonth = String.join("", dayOfMonthArray);
    String newTimeBucket = newDayOfMonth + timeString.substring(10, 14);

    // Convert the new timeBucket to a long and return it
    return Long.parseLong(newTimeBucket);
}

public long compressTimeBucket(long timeBucket, int dayStep) {

    timeBucket = timeBucket / dayStep;
    timeBucket *= dayStep;

    return timeBucket;
}

private static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 0 || dayStep > 14) {
        throw new IllegalArgumentException("dayStep must be a value between 0 and 14");
    }
    int lowest11Bits = (int) (timeBucket & 0x7FF);
    long highestYearMonth = timeBucket >> 11;
    long reFormattedTimeBucket = highestYearMonth << 11;
    if (dayStep > 0) {
        reFormattedTimeBucket += dayStep;
    }
    return reFormattedTimeBucket | lowest11Bits;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedTimeBucket = timeBucket;
    if(timeBucket % 100 == 0) {
        compressedTimeBucket = timeBucket + (dayStep - timeBucket % 100) % 100;
    }else{
        compressedTimeBucket = timeBucket - timeBucket % 100 + (dayStep - timeBucket % 100) % 100;
    }
    return compressedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    intutf8Size = 0;
    for (int i = index; i < index + len; i++) {
        int codePoint = str.codePointAt(i);
        if (codePoint <= 0x7F) {
            utf8Size += 1;
        } else if (codePoint <= 0x7FF) {
            utf8Size += 2;
        } else if (codePoint <= 0xFFFF) {
            utf8Size += 3;
        } else if (codePoint <= 0x1FFFFF) {
            utf8Size += 4;
        } else if (codePoint <= 0x3FFFFFF) {
            utf8Size += 5;
        } else if (codePoint <= 0x7FFFFFFF) {
            utf8Size += 6;
        } else {
            throw new IllegalArgumentException("Code point not valid: " + codePoint);
        }
    }
    return utf8Size;
}

public int computeUTF8Size(String str, int index, int len) {
    int utf8Size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            utf8Size++;
        } else if (c <= 0x7FF) {
            utf8Size += 2;
        } else if (c <= 0xFFFF) {
            utf8Size += 3;
        } else {
            utf8Size += 4;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int length) {
    int size = 0;
    for (int i = index; i < index + length; i++) {
        if (charAt(str, i) >= 0x10000) {
            size += 2;
        } else if (charAt(str, i) >= 0x800) {
            size += 1;
        }
    }
    return size;
}

