        Arrays.fill(byteArrayValue, (byte) 0);
    }
    if (byteOffset < 0 || byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException();
    }
    for (int i = 0; i < byteLength; i++) {
        putByte(byteArrayValue[i + byteOffset]);
    }
    return this;
}

public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
  if (byteArrayValue == null) {
    for (int i = 0; i < byteLength; i++) {
      this.bytes.add((byte) 0);
    }
    return this;
  }
  for (int i = byteOffset; i < byteOffset + byteLength; i++) {
    this.bytes.add(byteArrayValue[i]);
  }
  return this;
}

public ByteVector putByteArray(byteArrayValue, byteOffset, byteLength) {
        if (byteArrayValue == null) {
            this.ensureCapacity(byteArrayValue.length);
            for (int i = 0; i < byteLength; i++) {
                this.array[byteOffset + i] = 0;
            }
        } else {
            this.ensureCapacity(byteOffset + byteLength - 1);
            System.arraycopy(byteArrayValue, byteOffset, this.array, byteOffset, byteLength);
        }
        return this;
    }

public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength){
  if(byteArrayValue != null){
    if(byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length){
      throw new IndexOutOfBoundsException("Invalid offset or length");
    }
    // Check if byte vector needs to be resized
    if(this.size() < byteOffset + byteLength){
      resizeBuffer(byteOffset + byteLength);
    }
    System.arraycopy(byteArrayValue, byteOffset, this.buffer, byteOffset, byteLength);
  } else {
    // Fill with null bytes
    if(this.size() < byteOffset + byteLength){
      resizeBuffer(byteOffset + byteLength);
    }
    Arrays.fill(this.buffer, byteOffset, byteOffset + byteLength, (byte) 0);
  }
  return this;
}

