	// Assuming that LinkedBuffer and WriteSession are classes defined in the
	// current package, and that LinkedBuffer has a method to add bytes
	// (e.g. addByte()).
	for (int i = 0; i < str.length(); i++) {
		int codepoint = str.codePointAt(i);

		if (codepoint <= 0x7F) {
			lb.addByte((byte) codepoint);
		} else if (codepoint <= 0x7FF) {
			lb.addByte((byte) (0xC0 | (codepoint >> 6)));
			lb.addByte((byte) (0x80 | (codepoint & 0x3F)));
		} else if (codepoint <= 0xFFFF) {
			lb.addByte((byte) (0xE0 | (codepoint >> 12)));
			lb.addByte((byte) (0x80 | ((codepoint >> 6) & 0x3F)));
			lb.addByte((byte) (0x80 | (codepoint & 0x3F)));
		} else {
			lb.addByte((byte) (0xF0 | (codepoint >> 18)));
			lb.addByte((byte) (0x80 | ((codepoint >> 12) & 0x3F)));
			lb.addByte((byte) (0x80 | ((codepoint >> 6) & 0x3F)));
			lb.addByte((byte) (0x80 | (codepoint & 0x3F)));
		}
	}

	return lb;
}

