public LinkedBuffer writeUTF8(String str, WriteSession session, LinkedBuffer lb) {
    LinkedBuffer result = lb;
    result.writeUInt16(str.length());
    char[] chars = str.toCharArray();
    for(char c : chars) {
        if(c < 0x80) {
            result.writeByte(c);
        } else if(c < 0x800) {
            result.writeByte(0xC0 | (c >> 6));
            result.writeByte(0x80 | (c & 0x3F));
        } else if (c < 0x10000) {
            result.writeByte(0xE0 | (c >> 12));
            result.writeByte(0x80 | (c >> 6 & 0x3F));
            result.writeByte(0x80 | (c & 0x3F));
        } else {
            result.writeByte(0xF0 | (c >> 18));
            result.writeByte(0x80 | (c >> 12 & 0x3F));
            result.writeByte(0x80 | (c >> 6 & 0x3F));
            result.writeByte(0x80 | (c & 0x3F));
        }
    }
    return result;
}

