public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    // Extract path component from URI
    String pathComponent = u.getPath();
    // Initialize index of last encountered delimeter (starting from 0)
    int lastDelimeterIndex = 0;
    // Iterate over each character in path component
    for (int i = 0; i < pathComponent.length(); i++) {
        // If current character is a delimeter, split the segment and add it to the list
        if (pathComponent.charAt(i) == '/') {
            // Ignore leading slash if path is absolute
            if (lastDelimeterIndex == 0 && pathComponent.charAt(i) == '/') {
                lastDelimeterIndex++;
                continue;
            }
            String segment = pathComponent.substring(lastDelimeterIndex, i);
            // Decode segment if required
            segment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;
            pathSegments.add(new PathSegmentImpl(segment));
            lastDelimeterIndex = i + 1;
        }
    }
    // Add the final segment if there is any
    if (lastDelimeterIndex < pathComponent.length()) {
        String segment = pathComponent.substring(lastDelimeterIndex);
        // Decode segment if required
        segment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path.equals("")) {
        return pathSegments;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] pathComponents = path.split("/");
    for (String pathComponent : pathComponents) {
        String decodedPathComponent = decode ? urlDecode(pathComponent) : pathComponent;
        pathSegments.add(new PathSegmentImpl(decodedPathComponent));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u,boolean decode) {
  // check if the path is an absolute path component
  if (u.getPath().startsWith("/")) {
    // ignore the leading '/' character and treat it as a delimiter for the path segment
    u.getPath().substring(1);
  }

  // split the path component into individual path segments using '/' as a delimiter
  String[] pathSegments = u.getPath().split("/");

  // create a new list to store the path segments
  List<PathSegmentImpl> pathSegmentList = new ArrayList<>();

  // iterate through the path segments and add them to the list in decoded form
  for (int i = 0; i < pathSegments.length; i++) {
    PathSegmentImpl pathSegment = new PathSegmentImpl(pathSegments[i]);
    if (decode) {
      pathSegment.decode();
    }
    pathSegmentList.add(pathSegment);
  }

  // return the list of path segments
  return pathSegmentList;
}

private static List<PathSegmentImpl> decodePath(URI u, Boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<PathSegmentImpl>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    if (decode) {
        path = URIUtil.decode(path);
    }

    // Decode the path component of a URI as path segments.
    // The leading '/' is ignored and is not considered a delimitor of a path segment.
    String[] pathSegmentsArray = path.split("/");
    for (String pathSegment : pathSegmentsArray) {
        pathSegments.add(new PathSegmentImpl(pathSegment));
    }

    return pathSegments;
}

