private static int getNumArguments(String descriptor) {
    switch (descriptor) {
        case "null":
            return 0;
        case "boolean":
        case "int":
        case "long":
        case "float":
        case "double":
        case "byte":
        case "short":
        case "char":
            return 1;
        case "void":
            return 0;
        default:
