    double halfWidth = box.getWidth() / 2;
    double leftX = box.getX();
    double rightX = box.getX() + halfWidth;
    Box2D leftBox = new Box2D(leftX, box.getY(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(rightX, box.getY(), halfWidth, box.getHeight());
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
