public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
	Box2D[] boxes = new Box2D[2];
	double xMid = box.getWidth() / 2;

	boxes[0] = new Box2D(box.getMin().getX(), box.getMin().getY(), xMid, box.getMax().getY());
	boxes[1] = new Box2D(box.getMin().getX() + xMid, box.getMin().getY(), box.getMax().getX() - xMid, box.getMax().getY());

	return new Pair<Box2D,Box2D>(boxes[0], boxes[1]);
}

