public int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int size = 0;
    // Ensure that the LinkedBuffer is not null
    if (node == null) {
        return size;
    }

    // Write the value of the buffer
    size += out.writeUTF(node.getString());

    // Write the size of the buffer
    size += out.writeInt(node.getSize());

    // Iterate over the linked nodes
    for (LinkedBuffer child : node.getNode().getChildren()) {
        // Recursively write the child node
        size += writeTo(out, child);
    }

    return size;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    // Write the contents of the LinkedBuffer into the DataOutput
    for (Object obj : node) {
        out.writeObject(obj);
        totalSize += 1;
    }
    // Return the total content size of the buffer
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        final int size = out.write(node.data);
        totalSize += size;
        node = node.next;
    }
    return totalSize;
}

