    // Check if the end of the stream has been reached
    if (bytesRead < bufferSize) {
        // If so, resize the byte array to the number of bytes read
        byte[] buffer = new byte[bytesRead];
        // Copy the bytes from the byte array to the buffer
        System.arraycopy(bytes, 0, buffer, 0, bytesRead);
        // Set the buffer to the resized byte array
        this.buffer = buffer;
    } else {
        // If the end of the stream has not been reached, simply set the buffer to the byte array
        this.buffer = bytes;
    }
    // Set the read pointer to the start of the buffer
    readPointer = 0;
