    int n = in.read(buffer, 0, BUFFER_SIZE);
    while (n != -1) {
        int offset = this.maxPointer;
        int length = n;
        if (offset + length >= this.bytes.length) {
            // Grow the buffer if necessary.
            int newLength = (int)(1.5 * this.bytes.length);
            byte[] newBytes = new byte[newLength];
            System.arraycopy(this.bytes, 0, newBytes, 0, offset);
            this.bytes = newBytes;
        }
        // Append the array of bytes read from the InputStream to the end of the buffer.
        System.arraycopy(buffer, 0, this.bytes, offset, length);
        this.maxPointer = offset + length;
        // Read from the InputStream again.
        n = in.read(buffer, 0, BUFFER_SIZE);
    }
}

