        return value;
    } else if (value instanceof String) {
        return new java.lang.String((String) value).charAt(0);
    } else {
        throw new Exception("Cannot convert value of " + value.getClass() + " to java.lang.Character");
    }
}

public void convertToType(Class type, Object value) throws Exception {
        if (type == char.class || type == Character.class) {
            if (value instanceof Character) {
                return value;
            } else if (value instanceof Number) {
                return (char) ((Number) value).intValue();
            } else if (value instanceof String) {
                if (((String) value).length() != 1) {
                    throw new Exception("Cannot convert " + value + " to " + type.getSimpleName());
                }
                return ((String) value).charAt(0);
            } else {
                throw new Exception("Cannot convert " + value + " to " + type.getSimpleName());
            }
        } else {
            throw new Exception("Cannot convert " + value + " to " + type.getSimpleName());
        }
    }

