    } else {
        return convertToPrimitiveType(type, value);
    }
}

private Object convertToPrimitiveType(final Class<?> type,final Object value) throws Exception {
    if (type == Character.class) {
        return value instanceof Character ? (Character) value : (Character) value.toString().charAt(0);
    } else {
        return value;
    }
}

protected Object convertToType(final Class<?> type, final Object value) throws Exception {
        if (type.equals(Character.class) || type.equals(Character.TYPE)) {
            if (value instanceof CharSequence) {
                if (((CharSequence) value).length() == 1) {
                    return ((CharSequence) value).charAt(0);
                } else {
                    throw new SQLDataException("Length of String value greater than 1, cannot convert to Character");
                }
            } else if (value instanceof Number) {
                if (((Number) value).intValue() < 0xFFFF) {
                    return (char) ((Number) value).intValue();
                } else {
                    throw new SQLDataException("Value greater than 65535, cannot convert to Character");
                }
            } else {
                throw new SQLDataException("Cannot convert input value of type " + value.getClass().getName() + " to Character");
            }
        } else {
            throw new SQLDataException("Cannot convert to " + type.getName() + ", not a Character");
        }
    }

else if (value instanceof Integer) {
    return (char) (int) value;
  }

else if (value instanceof Long) {
    return (char) (long) value;
  }

else if (value instanceof String) {
    if (((String) value).length() != 1) {
      throw new Exception("Value cannot be converted to Character: length is not one");
    }
    return ((String) value).toCharArray()[0];
  }

