public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        return null;
    }
    int end = str.length() - 1;
    while (end >= 0 && Character.isWhitespace(str.charAt(end))) {
        end--;
    }
    return str.substring(0, end + 1);
}

public String trimTrailingWhitespace(String str) {
	int length = str.length();
	int startIdx = 0;
	int endIdx = length - 1;
	while (startIdx <= endIdx && Character.isWhitespace(str.charAt(startIdx))) {
		startIdx++;
	}
	while (endIdx >= 0 && Character.isWhitespace(str.charAt(endIdx))) {
		endIdx--;
	}
	return (startIdx == 0 && endIdx == length - 1) ? str : str.substring(startIdx, endIdx + 1);
}

