public static String unescapeJava(String str) {
        if (str == null)
            return null;

        int backslash = str.indexOf('\\');
        if (backslash == -1)
            return str;

        StringBuffer buffer = new StringBuffer(str.length());
        for (int i = 0; i < backslash; i++) {
            buffer.append(str.charAt(i));
        }
        while (backslash != -1) {
            char c = str.charAt(++backslash);
            switch (c) {
            case '\\': buffer.append('\\'); backslash = str.indexOf('\\', backslash + 1); break;
            case 'n': buffer.append('\n'); backslash = str.indexOf('\\', backslash + 1); break;
            default: throw new IllegalArgumentException("Invalid escape sequence \"\\" + c + "\"");
            }
        }
        for (int i = backslash; i < str.length(); i++) {
            buffer.append(str.charAt(i));
        }
        return buffer.toString();
    }

public static String unescapeJava(String str) {
    if (str == null) return null;
    int len = str.length();
    StringBuilder builder = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            c = str.charAt(++i);
            if (c == '\\') {
                builder.append('\\');
            } else if (c == 'n') {
                builder.append('\n');
            } else if (c == 'r') {
                builder.append('\r');
            } else if (c == 't') {
                builder.append('\t');
            } else if (c == 'f') {
                builder.append('\f');
            } else if (c == '\'') {
                builder.append('\'');
            } else if (c == '\"') {
                builder.append('\"');
            } else if (c == 'b') {
                builder.append('\b');
            } else if (c == 's') {
                builder.append(' ');
            } else if (c == 'v') {
                builder.append(' '); // non-breaking space
            } else if (c == 'x') {
                if (i+4 < len) {
                    char high = str.charAt(++i);
                    char low = str.charAt(++i);
                    builder.append((char) Integer.parseInt(String.valueOf(high) + low, 16));
                } else {
                    throw new IllegalArgumentException("Incomplete hex code");
                }
            } else {
                builder.append('\\');
                builder.append(c);
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

