private String unescapeId(String input){
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char nextC = input.charAt(i + 1);
            if (nextC == 'u') {
                int j = i + 2;
                while (j + 3 < input.length() && input.charAt(j) == 'u') {
                    j += 4;
                }
                output.append(input.substring(i, j + 1));
                i = j;
            } else if (nextC == 'U') {
                int j = i + 2;
                while (j + 3 < input.length() && input.charAt(j) == 'U') {
                    j += 4;
                }
                output.append(input.substring(i, j + 1));
                i = j;
            } else {
                output.append(c);
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            c = input.charAt(++i);
            switch (c) {
                case '.':
                    output.append("\\\\");
                    break;
                case '""':
                    output.append('"');
                    break;
                default:
                    output.append('\\').append(c);
                    break;
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    // Check if the input is not null or empty
    if (input == null || input.trim().isEmpty()) {
        return input;
    }

    // Get the first character of the input
    char firstChar = input.charAt(0);

    // Check if the first character is an underscore
    if (firstChar == '_') {
        // If it is, remove the first character and return the rest of the string
        return input.substring(1);
    }

    return input;
}

