    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    boolean result = false;
    if (this.size() != 0) {
        if (this.head == node) {
            this.head = node.next;
            if (this.head != null) {
                this.head.prev = null;
            }
            result = true;
        } else if (this.tail == node) {
            this.tail = node.prev;
            if (this.tail != null) {
                this.tail.next = null;
            }
            result = true;
        } else {
            ListNodeImpl<E> prev = node.prev;
            ListNodeImpl<E> next = node.next;
            prev.next = next;
            next.prev = prev;
            result = true;
        }
    }
    return result;
}

public static Boolean unlink(ListNodeImpl<E> node) {
    // Remove the given node from the list
    if (node == null) {
        return false;
    }
    if (node.next == null) {
        return false;
    }

    // Remove the node from the list
    ListNodeImpl<E> previousNode = node.previous;
    ListNodeImpl<E> nextNode = node.next;
    if (previousNode != null) {
        previousNode.next = nextNode;
    }
    if (nextNode != null) {
        nextNode.previous = previousNode;
    }

    // Update the list size
    size--;

    // Return whether the node was successfully removed
    return true;
}

