private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> previous = node.getPreviousNode();
    ListNodeImpl<E> next = node.getNextNode();

    if (previous != null) {
        previous.setNextNode(next);
    }
    if (next != null) {
        next.setPreviousNode(previous);
    }

    node.setPreviousNode(null);
    node.setNextNode(null);

    return true;
}

