private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    // Iterate through each element in the bounds list
    for (Integer bound : bounds) {
        // Add the current bound to the suffix sum list
        suffixSum.add(bound);

        // Increment the sum by the current bound
        sum += bound;
    }

    // Return the computed suffix sum and sum
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long sumOfBounds = 0;

    for (int bound : bounds) {
        suffixSumList.add(suffixSumList.isEmpty() ? bound : suffixSumList.get(suffixSumList.size() - 1) + bound);
        sumOfBounds += bound;
    }

    return new Pair<List<Integer>, Long>(suffixSumList, sumOfBounds);
}

