public static final <V> void reverse(V[] arr, int from, int to) {

    // Handle invalid arguments
    if (arr == null || from < 0 || to < 0 || to < from || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("Invalid arguments");
    }

    // Swap ends of range
    while (from < to) {
        arr.swap(from, to);
        from++;
        to--;
    }
}

