    if (arr == null || arr.length == 0 || from < 0 || from >= arr.length || to < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

