private List<Pair<Integer, Integer>> computeLocalSeparator(E e) {
    List<Integer> vertices = G.getVertices();
    List<Integer> neighbors = graph.getNeighbors(e);
    List<Pair<Integer, Integer>> localSeparator = new ArrayList<>();
    for (int i = 0; i < vertices.size(); i++) {
        int v = vertices.get(i);
        if (!neighbors.contains(v)) {
            localSeparator.add(new Pair<>(i, v));
        }
    }
    return localSeparator;
}

