public Pair<List<Pair<Integer,Integer>>,E> computeLocalSeparator(E edge, int entryIndex) {
    List<Pair<Integer,Integer>> separator = new ArrayList<>();
    for (int v = 1; v < edge.getEntry(entryIndex).size(); v++) {
        separator.add(edge.getEntry(entryIndex).get(v));
