private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    boolean isClique = true;
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1.equals(vertex2)) {
                continue;
            }
            if (!graph.hasEdge(vertex1, vertex2)) {
                isClique = false;
                break;
            }
        }
        if (!isClique) {
            break;
        }
    }
    return isClique;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    boolean isClique = true;
    // Iterate over all pairs of vertices in the given vertices set
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            // If v1 and v2 are not in the same connected component, then the graph is not a clique
            if (!graph.connected(v1, v2)) {
                isClique = false;
                break;
            }
        }
        // If any pair of vertices is not in the same connected component, then the graph is not a clique
        if (!isClique) {
            break;
        }
    }
    return isClique;
}

