    char[] chars = s.toCharArray();
    StringBuilder encodedString = new StringBuilder();

    for (char c : chars) {
        if (c == '{') {
            encodedString.append("%7B");
        } else if (c == '}') {
            encodedString.append("%7D");
        } else {
            encodedString.append(c);
        }
    }

