  String[] pathSegments = path.split("/");
  String[] relativePathSegments = relativePath.split("/");
  int length = Math.min(pathSegments.length, relativePathSegments.length);
  int i;
  for (i = 0; i < length; i++) {
    if (!pathSegments[i].equals(relativePathSegments[i])) break;
  }
  StringBuilder result = new StringBuilder();
  for (int j = 0; j < i; j++) {
    result.append(pathSegments[j]);
    result.append("/");
  }
  for (int j = i; j < relativePathSegments.length; j++) {
    result.append(relativePathSegments[j]);
    result.append("/");
  }
