public int indexOfExtension(String filename) {
	int dotIndex = -1;
	int nextChar = -1;
	for (int i = filename.length() - 1; i >= 0; i--) {
		if (filename.charAt(i) == '.') {
			dotIndex = i;
		}
		if (filename.charAt(i) == '\\' || filename.charAt(i) == '/') {
			nextChar = i;
			break;
		}
	}
	if (dotIndex > nextChar) {
		return dotIndex;
	} else {
		return -1;
	}
}

