public static int indexOfExtension(String filename) {
    int extIndex = filename.lastIndexOf(".");
    if (extIndex > 0 && filename.charAt(extIndex - 1) != java.io.File.separatorChar) {
        // Don't let there be any directory separators after the last dot
        return extIndex;
    } else {
        // There was no extension (or only a dot separating the filename and extension), therefore indexOfExtension returns -1
        return -1;
    }
}

public static int indexOfLastSeparator(String filename) {
    if (filename.indexOf("/") >= 0) {
        return filename.lastIndexOf("/");
    } else if (filename.indexOf("\\") >= 0) {
        return filename.lastIndexOf("\\");
    } else {
        return -1;
    }
}

