    if (filename == null){
        return -1;
    }
    int extensionIndex = filename.lastIndexOf('.');
    if (extensionIndex == -1){
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    return extensionIndex > lastSeparator ? extensionIndex : -1;
}

int indexOfExtension(String filename){

    if(filename === null) return -1;

    int sepIndex = indexOfLastSeparator(filename);

    if(sepIndex === -1) return -1;

    if(filename.charAt(sepIndex) !== '.') return -1;

    int lastDot = filename.substring(sepIndex).indexOf('.')) + sepIndex;

    if(filename.substring(lastDot+1).indexOf( '/') !== -1) return - 1;

    return lastDot;
}

