private static boolean substringMatch(String str, int index, String substring) {
    if (str == null || substring == null) {
        throw new IllegalArgumentException("str and substring cannot be null");
    }

    if (index >= str.length() || index < 0) {
        throw new IllegalArgumentException("index is out of bounds");
    }

    if (substring.isEmpty()) {
        throw new IllegalArgumentException("substring cannot be empty");
    }

    if (substring.length() > str.length() - index) {
        return false;
    }

    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

