private static boolean isInTimeRange(String line, long startTime, long endTime) {
    String[] tokens = line.split(" ");
    long timestamp = Long.parseLong(tokens[0]);
    return timestamp >= startTime && timestamp <= endTime;
}

private static ThreadSnapshot parseThreadSnapshotFromLine(String line) {
    String[] tokens = line.split(" ");
    long timestamp = Long.parseLong(tokens[0]);
    long id = Long.parseLong(tokens[1]);
    long cpu = Long.parseLong(tokens[2]);
    long locals = Long.parseLong(tokens[3]);
    return new ThreadSnapshot(timestamp, id, cpu, locals);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (line.startsWith(timeRange.getStartTime())) {
                    ThreadSnapshot threadSnapshot = new ThreadSnapshot(line, timeRange.getStartTime(), timeRange.getEndTime());
                    threadSnapshots.add(threadSnapshot);
                    break;
                }
            }
        }
    }

    return threadSnapshots;
}
